hit(key) { const entry=pin(key); try { for(;;) {
 const stripe=entry.stripe(clock.peek()%300); lock(stripe);
 try { const now=clock.nowMonotone();
  if(stripeOf(now%300)!==stripe)continue; // finally unlocks before the loop retries
  const slot=entry.slot(now%300);
  const next=slot.second===now?checkedAdd(slot.count,1):1;
  slot.second=now;slot.count=next;return;
 }finally{unlock(stripe);}
 }}finally{unpin(entry);} }
